use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/signed-complex-caller176";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(n:&str,v:&Value){fs::write(format!("{R}/{n}"),serde_json::to_vec_pretty(v).unwrap()).unwrap();}
fn main(){let mode=std::env::args().nth(1).unwrap();if mode=="prepare"{
 assert!(!Path::new(&format!("{R}/link-plan.json")).exists());assert_eq!(read(format!("{R}/native-fixed/result.json"))["status"],"complete");let initial=fs::read_to_string(format!("{R}/native/core-off/stdout.log")).unwrap();assert!(initial.contains("127 passed; 2 failed"));let on=read(format!("{R}/native-fixed/core-on/tests.json"));assert_eq!(on["unfiltered"],true);assert_eq!(on["passed_tests"].as_array().unwrap().len(),129);for n in["borrowed_signed_g2_generator_oracle_tails_and_reuse","owned_g2_prefix_generator_oracle_tails_and_reuse"]{let t=read(format!("{R}/native-fixed/repair-off-{n}/tests.json"));assert_eq!(t["passed_tests"].as_array().unwrap().len(),1);}
 let mut pins:BTreeMap<String,String>=serde_json::from_value(read(format!("{R}/build-fixed-pins.json"))).unwrap();for(p,h)in&pins{assert_eq!(hash(p),*h);}let mut steps=Vec::new();for label in["off","on"]{let info=read(format!("{R}/artifacts-{label}.json"));for(p,h)in info["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins.insert(p.clone(),h.as_str().unwrap().into());}let library=info["libraries"]["zopro_core"].as_str().unwrap();let dependencies=Path::new(library).parent().unwrap();let mut argv=vec!["/home/ubuntu/.rustup/toolchains/1.98.1-x86_64-unknown-linux-gnu/bin/rustc".to_string(),"--edition=2021".into(),"-O".into(),"-C".into(),"target-cpu=native".into(),"-C".into(),"lto=fat".into(),"-C".into(),"codegen-units=1".into(),"-L".into(),format!("dependency={}",dependencies.display())];for(name,p)in info["libraries"].as_object().unwrap(){argv.extend(["--extern".into(),format!("{name}={}",p.as_str().unwrap())]);}argv.extend([format!("{R}/probe.rs"),"-o".into(),format!("{R}/{label}-probe")]);steps.push(json!({"kind":"command","name":format!("link-{label}"),"argv":argv,"environment":{},"timeout_seconds":600}));}
 for name in["links.rs","links","probe.rs","perf.rs","artifacts-off.json","artifacts-on.json","native-fixed/result.json"]{let p=format!("{R}/{name}");pins.insert(p.clone(),hash(p));}save("link-pins.json",&json!(pins));save("link-plan.json",&json!({"version":1,"source_pins":format!("{R}/link-pins.json"),"steps":steps}));println!("Prepared explicit optimized OFF/ON links; native129coverage/qualifiedchild and coherent frozen sets checked");
 }else if mode=="seal"{
 assert_eq!(read(format!("{R}/links/result.json"))["status"],"complete");for label in["off","on"]{let info=read(format!("{R}/artifacts-{label}.json"));let argv=read(format!("{R}/links/link-{label}/command.json"));for required in["-O","target-cpu=native","lto=fat","codegen-units=1"]{assert!(argv["argv"].as_array().unwrap().contains(&json!(required)));}let mut pins:BTreeMap<String,String>=serde_json::from_value(info["input_pins"].clone()).unwrap();for n in["probe.rs","perf.rs"]{let p=format!("{R}/{n}");pins.insert(p.clone(),hash(p));}let binary=format!("{R}/{label}-probe");save(&format!("probe-{label}.json"),&json!({"binary":binary,"sha256":hash(&binary),"input_pins":pins,"native_flags":info["rustflags"],"lto":"fat","library_manifest":info}));}println!("Sealed OFF/ON optimized linked probes; no timings");
 }else{panic!()}}
